import socket, io, time

class TimeoutSocket:
    def __init__(self, sock, deadline_secs=5.0, read_timeout=5.0):
        self._sock = sock
        self._deadline = time.monotonic() + deadline_secs
        self._read_timeout = read_timeout

    def recv(self, bufsize, flags=0):
        remaining = self._deadline - time.monotonic()
        if remaining <= 0:
            raise socket.timeout('Request deadline exceeded')
        self._sock.settimeout(max(0.01, min(self._read_timeout, remaining)))
        return self._sock.recv(bufsize, flags)

    def recv_into(self, buffer, nbytes=0, flags=0):
        remaining = self._deadline - time.monotonic()
        if remaining <= 0:
            raise socket.timeout('Request deadline exceeded')
        self._sock.settimeout(max(0.01, min(self._read_timeout, remaining)))
        return self._sock.recv_into(buffer, nbytes, flags)

    def makefile(self, mode='r', buffering=-1, *args, **kwargs):
        # We can wrap the underlying makefile or set sock.settimeout directly!
        return self._sock.makefile(mode, buffering, *args, **kwargs)

    def __getattr__(self, name):
        return getattr(self._sock, name)

