#!/usr/bin/env python3
"""DMGHG Local Bridge Service

Headless HTTP bridge for installed DMGHG Windows native runtime.
Binds strictly to 127.0.0.1 (default port 18002).
"""
import argparse
import ctypes
import http.server
import io
import json
import os
from pathlib import Path
import shutil
import socket
import sys
import tempfile
import threading
import time
import urllib.parse


def installed_version(exe_path):
    """Read PE version metadata from installed executable."""
    version_dll = ctypes.windll.version
    size = version_dll.GetFileVersionInfoSizeW(str(exe_path), None)
    if not size:
        raise RuntimeError("Cannot read the installed application's version metadata")
    buffer = ctypes.create_string_buffer(size)
    if not version_dll.GetFileVersionInfoW(str(exe_path), 0, size, buffer):
        raise RuntimeError("Cannot read application version info")
    info = ctypes.c_void_p()
    length = ctypes.c_uint()
    if not version_dll.VerQueryValueW(buffer, "\\", ctypes.byref(info), ctypes.byref(length)):
        raise RuntimeError("Application version structure is missing")
    fields = ctypes.cast(info, ctypes.POINTER(ctypes.c_uint32))
    if fields[0] != 0xFEEF04BD or length.value < 52:
        raise RuntimeError("Application version structure is invalid")
    return f"{fields[2] >> 16}.{fields[2] & 65535}.{fields[3] >> 16}"


class Bridge:
    READ_COMMANDS = {
        "app.ping", "catalog.get_channels", "catalog.get_banners",
        "catalog.get_video_list", "catalog.search_video", "catalog.get_video_key",
        "catalog.get_video_detail", "catalog.get_channel_detail", "video.play",
    }

    def __init__(self, app_dir):
        if os.name != "nt":
            raise RuntimeError("The installed bridge requires Windows x64 Python")
        self.app_dir = Path(app_dir).resolve(strict=True)
        self.dll_path = self.app_dir / "electron_bridge.dll"
        if not self.dll_path.is_file():
            raise RuntimeError("electron_bridge.dll is missing from the selected application")

        self.state_root = Path(tempfile.mkdtemp(prefix="dmghg-headless-"))
        os.environ["DMGHG_TEST_DATA_ROOT"] = str(self.state_root)
        os.environ["RUST_LOG"] = "error"

        self.dll = ctypes.CDLL(str(self.dll_path))
        self.dll.dmghg_service_new.argtypes = [ctypes.c_char_p, ctypes.c_char_p]
        self.dll.dmghg_service_new.restype = ctypes.c_void_p
        self.dll.dmghg_service_handle_command_json.argtypes = [ctypes.c_void_p, ctypes.c_char_p]
        self.dll.dmghg_service_handle_command_json.restype = ctypes.c_void_p
        self.dll.dmghg_string_free.argtypes = [ctypes.c_void_p]
        self.dll.dmghg_service_free.argtypes = [ctypes.c_void_p]

        self.lock = threading.RLock()
        self.version = installed_version(self.app_dir / "dmghg.exe")
        self.handle = self.dll.dmghg_service_new(b"dmghg-flutter", self.version.encode("ascii"))
        if not self.handle:
            raise RuntimeError("The installed bridge could not initialize")

    def call(self, command, payload=None):
        if command not in self.READ_COMMANDS:
            raise ValueError(f"Command '{command}' is outside the inspection allowlist")
        request = {
            "request_id": "headless-rpc",
            "protocol_version": 1,
            "command": command,
            "payload": payload or {}
        }
        with self.lock:
            previous = Path.cwd()
            try:
                os.chdir(self.app_dir)
                ptr = self.dll.dmghg_service_handle_command_json(
                    self.handle, json.dumps(request, ensure_ascii=False).encode("utf-8")
                )
                if not ptr:
                    raise RuntimeError("Bridge returned a null response")
                try:
                    response = json.loads(ctypes.string_at(ptr).decode("utf-8"))
                finally:
                    self.dll.dmghg_string_free(ptr)
            finally:
                os.chdir(previous)

        if response.get("ok") is not True:
            error = response.get("error", {})
            raise RuntimeError(f"{error.get('code', 500)}: {error.get('message', 'Unknown error')}")
        return response.get("data")

    def close(self):
        with self.lock:
            if self.handle:
                self.dll.dmghg_service_free(self.handle)
                self.handle = None
        if self.state_root.exists():
            try:
                shutil.rmtree(self.state_root, ignore_errors=True)
            except Exception:
                pass


class DeadlineStream(io.RawIOBase):
    """Enforces an overall wall-clock deadline on socket reads (e.g. 5.0 seconds)."""
    def __init__(self, sock, max_duration=5.0):
        self.sock = sock
        self.deadline = time.monotonic() + max_duration

    def readinto(self, b):
        remaining = self.deadline - time.monotonic()
        if remaining <= 0:
            raise socket.timeout("Request deadline exceeded")
        self.sock.settimeout(max(0.01, remaining))
        try:
            n = self.sock.recv_into(b)
            if n is None:
                return 0
            return n
        except socket.timeout:
            raise socket.timeout("Request deadline exceeded")

    def readable(self):
        return True


class BridgeRequestHandler(http.server.BaseHTTPRequestHandler):
    protocol_version = "HTTP/1.1"

    def setup(self):
        super().setup()
        # 5.0 seconds overall deadline for request reading (well within the 8.0s limit)
        self.rfile = io.BufferedReader(DeadlineStream(self.connection, max_duration=5.0))

    def handle_one_request(self):
        try:
            super().handle_one_request()
        except (socket.timeout, TimeoutError):
            self.close_connection = True
            try:
                self.send_error(408, "Request Timeout")
            except Exception:
                pass

    def log_message(self, format, *args):
        # Keep stdout/stderr silent to avoid dumping signed URLs or polluting logs
        pass

    def send_json(self, data, status=200):
        body = json.dumps(data, ensure_ascii=False).encode("utf-8")
        self.send_response(status)
        self.send_header("Content-Type", "application/json; charset=utf-8")
        self.send_header("Content-Length", str(len(body)))
        self.send_header("Access-Control-Allow-Origin", "*")
        self.send_header("Connection", "close")
        self.end_headers()
        self.wfile.write(body)

    def send_error_json(self, message, code=400, status=400):
        self.send_json({"ok": False, "error": {"code": code, "message": message}}, status=status)

    def do_GET(self):
        try:
            parsed = urllib.parse.urlsplit(self.path)
            path = parsed.path
            qs = urllib.parse.parse_qs(parsed.query)

            if path == "/ping":
                self.send_json({
                    "ok": True,
                    "version": self.server.bridge.version,
                    "data": {"version": self.server.bridge.version}
                })
                return

            if path in ("/channels", "/api/channels"):
                data = self.server.bridge.call("catalog.get_channels")
                self.send_json({"ok": True, "data": data})
                return

            if path == "/api/list":
                channel_id = int(qs.get("channel", ["20"])[0])
                page_num = int(qs.get("page", ["1"])[0])
                data = self.server.bridge.call("catalog.get_video_list", {"channel": channel_id, "page": page_num})
                self.send_json({"ok": True, "data": data, **(data or {})})
                return

            if path == "/api/search":
                key = qs.get("key", [""])[0]
                page_num = qs.get("page", ["1"])[0]
                data = self.server.bridge.call("catalog.search_video", {"key": key, "page": str(page_num)})
                self.send_json({"ok": True, "data": data, **(data or {})})
                return

            if path == "/api/detail":
                vid = qs.get("id", [""])[0]
                if not vid:
                    self.send_error_json("Missing id parameter", status=400)
                    return
                data = self.server.bridge.call("catalog.get_video_detail", {"id": str(vid)})
                self.send_json({"ok": True, "data": data, **(data or {})})
                return

            if path == "/api/play":
                vid = qs.get("id", [""])[0]
                part = qs.get("part", [""])[0]
                play = qs.get("play", [""])[0]
                payload = {"id": str(vid), "part": str(part), "play": str(play), "resolve": True}
                data = self.server.bridge.call("video.play", payload)
                default_idx = data.get("default", 0)
                variants = data.get("list", [])
                variant = variants[default_idx] if variants and default_idx < len(variants) else (variants[0] if variants else {})
                play_url = variant.get("url", "")
                headers = variant.get("headers") or {}
                self.send_json({"ok": True, "url": play_url, "headers": headers, "data": data})
                return

            self.send_error_json(f"Not found: {path}", status=404)
        except (socket.timeout, TimeoutError):
            pass
        except Exception as e:
            self.send_error_json(str(e), code=500, status=500)

    def do_POST(self):
        try:
            parsed = urllib.parse.urlsplit(self.path)
            if parsed.path != "/call":
                self.send_error_json(f"Not found: {parsed.path}", status=404)
                return

            content_len_hdr = self.headers.get("Content-Length", 0)
            try:
                content_len = int(content_len_hdr)
            except ValueError:
                self.send_error_json("Invalid Content-Length", status=400)
                return

            if content_len > 1024 * 1024:
                self.send_error_json("Payload too large", status=413)
                return

            body = self.rfile.read(content_len)
            try:
                req_data = json.loads(body.decode("utf-8"))
            except Exception as e:
                self.send_error_json(f"Invalid JSON: {e}", status=400)
                return

            command = req_data.get("command")
            payload = req_data.get("payload", {})
            if not command:
                self.send_error_json("Missing command", status=400)
                return

            try:
                res = self.server.bridge.call(command, payload)
                self.send_json({"ok": True, "data": res})
            except ValueError as e:
                self.send_error_json(str(e), code=403, status=403)
            except Exception as e:
                self.send_error_json(str(e), code=500, status=500)
        except (socket.timeout, TimeoutError):
            pass
        except Exception as e:
            self.send_error_json(str(e), code=500, status=500)


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--app-dir", required=True, help="Path to installed application directory")
    parser.add_argument("--port", type=int, default=18002, help="Loopback port to bind (default: 18002)")
    parser.add_argument("--host", default="127.0.0.1", help="Loopback interface (strictly 127.0.0.1)")
    args = parser.parse_args()

    if args.host not in ("127.0.0.1", "localhost"):
        print("Error: For security, only 127.0.0.1 loopback binding is permitted.")
        sys.exit(1)

    bridge = Bridge(args.app_dir)
    server_address = ("127.0.0.1", args.port)

    class BridgeServer(http.server.ThreadingHTTPServer):
        daemon_threads = True
        allow_reuse_address = True

        def __init__(self, addr, handler_cls, b_inst):
            self.bridge = b_inst
            super().__init__(addr, handler_cls)

    httpd = BridgeServer(server_address, BridgeRequestHandler, bridge)
    print(f"DMGHG Bridge running at [REDACTED_URL] (version {bridge.version})")
    sys.stdout.flush()

    try:
        httpd.serve_forever()
    except KeyboardInterrupt:
        pass
    finally:
        httpd.server_close()
        bridge.close()


if __name__ == "__main__":
    main()

